declare(strict_types=1);use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);try{if(isset($_GET['error']))throw new RuntimeException((string)$_GET['error']);$result=$externalIdentity->callback((string)($_GET['state']??''),(string)($_GET['code']??''));if(!$auth->loginVerifiedUser((int)$result['user_id'],(int)$result['auth_level'],'external'))throw new RuntimeException('account_not_available');$requiredActions->refreshAutomaticCompletions((int)$result['user_id']);Web::redirect((string)$result['return_path']);}catch(Throwable $e){$audit->write('external_login.failed','denied',null,null,null,substr($e->getMessage(),0,500));http_response_code(401);Web::page('Logowanie zewnętrzne','<section class="card narrow"><h1>Logowanie nie powiodło się</h1><div class="code">'.Web::e($e->getMessage()).'</div><a class="button" href="/login">Powrót</a></section>');}
